const D = { density: .55, scale: 1, energy: .6, speed: 1, hue: 210, wind: .3, spin: 1, style: 'paper', act: 'fall', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const sty = P.style;
const N = Math.max(10, Math.min(150, Math.round(20 + P.density * 130)));

// rebuild piece table on seed / count change
if (!S.cf || S.cn !== N || S.cseed !== P.seed) {
  S.cf = [];
  for (let i = 0; i < N; i++) {
    S.cf.push({
      col: fr(i),
      y0: fr(i + 1),
      sp: 0.55 + fr(i + 2) * 0.9,
      ph: fr(i + 3) * TAU,
      hu: (fr(i + 4) - 0.5) * 80,
      sz: 0.6 + fr(i + 5) * 1.0,
      wob: 0.5 + fr(i + 6) * 1.3,
      spin: (fr(i + 7) - 0.5) * 2.4,
      shp: Math.floor(fr(i + 8) * 3)
    });
  }
  S.cn = N; S.cseed = P.seed;
}

const t = K.t;
const inten = 0.5 + 0.5 * K.intensity;
const fallSpd = (0.05 + 0.15 * P.energy) * P.speed * inten;
const windX = P.wind * (0.5 + 0.5 * Math.sin(t * 0.13));
const gust = K.pulse * 0.04 * P.energy;
const sparkle = A.treble * 12;
const sec = ((Math.floor(K.section) % 8) + 8) % 8;

// act programs
const ACT = {
  fall:  { swirl: 0, up: 0, gustK: 1 },
  swirl: { swirl: 1, up: 0, gustK: 0.6 },
  burst: { swirl: 0, up: (sec % 2 === 0) ? 0.6 : 0.1, gustK: 2.2 } };
const ac = ACT[P.act] || ACT.fall;

const add = (sty === 'mylar' || sty === 'streak');
push();
rectMode(CENTER);
noStroke();
if (add) blendMode(ADD);

function drawShape(w, shp) {
  if (shp === 0) rect(0, 0, w * 1.7, w);
  else if (shp === 1) triangle(-w * 0.9, w * 0.7, w * 0.9, w * 0.7, 0, -w * 0.9);
  else ellipse(0, 0, w * 1.4, w * 1.4);
}

for (let i = 0; i < N; i++) {
  const c = S.cf[i];
  let fy = (c.y0 + fallSpd * c.sp * t - ac.up * (0.5 + 0.5 * Math.sin(t * 1.3 + c.ph))) % 1.2;
  if (fy < 0) fy += 1.2;
  const y = fy * (height * 1.2) - height * 0.1;
  const swirlX = ac.swirl * Math.sin(fy * TAU * 1.5 + c.ph + t * 0.4) * u * 0.12;
  const x = c.col * width
    + Math.sin(t * c.wob * 0.6 + c.ph) * u * 0.03 * c.wob
    + windX * u * 0.14 * ac.gustK
    + gust * u * Math.sin(c.ph) * ac.gustK
    + swirlX;
  const a = c.ph + t * c.spin * P.spin * 1.6 + K.beat * 0.15;
  const sq = 0.35 + 0.65 * Math.abs(Math.sin(a));
  const w = u * 0.02 * P.scale * c.sz;

  push();
  translate(x, y);
  rotate(a * 0.6);
  scale(1, sq);

  if (sty === 'mylar') {
    const h = hw(P.hue + c.hu + Math.sin(a) * 70);
    fill(h, 45, 100, 42 + sparkle);
    drawShape(w * 1.1, c.shp);
    fill(hw(h + 30), 20, 100, 30 + sparkle);
    ellipse(0, -w * 0.2, w * 0.7, w * 0.7);
  } else if (sty === 'streak') {
    const h = hw(P.hue + c.hu);
    const len = u * (0.05 + 0.09 * P.energy) * (0.6 + 0.4 * c.sz);
    fill(h, 55, 100, 26 + sparkle * 0.7);
    rect(0, 0, w * 0.5, len);
    fill(hw(h + 20), 30, 100, 34);
    rect(0, -len * 0.25, w * 0.28, len * 0.5);
  } else if (sty === 'riso') {
    fill(hw(P.hue), 82, 88, 90);
    drawShape(w, c.shp);
    push(); translate(w * 0.18, w * 0.14);
    fill(hw(P.hue + 160), 78, 92, 62);
    drawShape(w * 0.9, c.shp); pop();
  } else if (sty === 'ink') {
    fill(hw(P.hue + c.hu * 0.2), 14, 20, 86);
    drawShape(w, c.shp);
    fill(hw(P.hue + c.hu * 0.2), 8, 8, 60);
    ellipse(w * 0.14, w * 0.1, w * 0.55, w * 0.7);
  } else {
    // paper (default) — matte, two-tone face/back
    const front = sq > 0.55;
    fill(hw(P.hue + c.hu), front ? 60 : 44, front ? 92 : 62, 92);
    drawShape(w, c.shp);
    if (front) { fill(hw(P.hue + c.hu), 30, 100, 22 + sparkle); ellipse(-w * 0.25, -w * 0.2, w * 0.6, w * 0.5); }
  }
  pop();
}

if (add) blendMode(BLEND);
pop();
drawingContext.shadowBlur = 0;
